// This is not autogenerated.
package errorcode

import (
	"errors"
	"fmt"
	"slices"
)

// This file is hand-written. It holds the rules of the error construct that
// JSON Schema cannot state (docs/error-definition-contract.md), mirrored by
// typescript/errors/errorDefinition.ts.

// ContractError is one broken rule of the error contract, with the JSON path
// of the value that breaks it.
type ContractError struct {
	Path    string
	Message string
}

func (e *ContractError) Error() string {
	if e.Path == "" {
		return e.Message
	}
	return e.Path + ": " + e.Message
}

func contractErrorf(path, format string, args ...any) error {
	return &ContractError{Path: path, Message: fmt.Sprintf(format, args...)}
}

// FlattenProbableCauses derives the flat lists earlier consumers read from
// nested causes: each cause's description in order, and each remediation's
// description walking the causes, then their remediations, in order, with
// each remediation ID kept the first time it appears. Nil causes yield two
// empty, non-nil lists.
func FlattenProbableCauses(causes []ProbableCause) (probableCause, suggestedRemediation []string) {
	probableCause = make([]string, 0, len(causes))
	suggestedRemediation = []string{}
	seen := map[string]bool{}
	for _, cause := range causes {
		probableCause = append(probableCause, cause.Description)
		for _, remediation := range cause.Remediations {
			if seen[remediation.ID] {
				continue
			}
			seen[remediation.ID] = true
			suggestedRemediation = append(suggestedRemediation, remediation.Description)
		}
	}
	return probableCause, suggestedRemediation
}

// EffectivePolicy is the policy a client acts on: the remediation's own,
// ActionPolicyManual when it is omitted, and ActionPolicyManual for a value
// this version does not know, so a remediation is never run by mistake.
func (r Remediation) EffectivePolicy() ActionPolicy {
	if r.ActionPolicy == nil {
		return ActionPolicyManual
	}
	switch *r.ActionPolicy {
	case ActionPolicyAutomatic, ActionPolicyRequiresApproval:
		return *r.ActionPolicy
	default:
		return ActionPolicyManual
	}
}

func sameRemediation(a, b Remediation) bool {
	return a.ID == b.ID && a.Description == b.Description &&
		equalPtr(a.Action, b.Action) && equalPtr(a.ActionPolicy, b.ActionPolicy)
}

func equalPtr[T comparable](a, b *T) bool {
	if a == nil || b == nil {
		return a == b
	}
	return *a == *b
}

// ValidateProbableCauses checks nested causes: cause IDs are unique, a
// remediation ID repeated under several causes names one remediation with
// identical fields, and every automatic or requiresApproval remediation has
// an action. path prefixes each error's JSON path, for example
// "probableCauses". It is shared by ErrorDefinition and the event
// construct's EventError.
func ValidateProbableCauses(causes []ProbableCause, path string) error {
	var errs []error
	causeIDs := map[string]bool{}
	remediations := map[string]Remediation{}
	for i, cause := range causes {
		causePath := fmt.Sprintf("%s[%d]", path, i)
		if causeIDs[cause.ID] {
			errs = append(errs, contractErrorf(causePath+".id", "cause id %q is not unique", cause.ID))
		}
		causeIDs[cause.ID] = true
		for j, remediation := range cause.Remediations {
			remPath := fmt.Sprintf("%s.remediations[%d]", causePath, j)
			if first, ok := remediations[remediation.ID]; !ok {
				remediations[remediation.ID] = remediation
			} else if !sameRemediation(first, remediation) {
				errs = append(errs, contractErrorf(remPath, "remediation id %q names two different remediations; a shared remediation is repeated with identical fields", remediation.ID))
			}
			if remediation.ActionPolicy != nil && (*remediation.ActionPolicy == ActionPolicyAutomatic || *remediation.ActionPolicy == ActionPolicyRequiresApproval) &&
				(remediation.Action == nil || *remediation.Action == "") {
				errs = append(errs, contractErrorf(remPath+".action", "actionPolicy %q needs an action", *remediation.ActionPolicy))
			}
		}
	}
	return errors.Join(errs...)
}

// ValidateFlatLists checks that flat lists carried beside nested causes are
// the lists FlattenProbableCauses derives. Without nested causes the flat
// lists are unpaired and there is nothing to check. prefix is prepended to
// the field names, for example "errors[0].".
func ValidateFlatLists(causes *[]ProbableCause, probableCause, suggestedRemediation *[]string, prefix string) error {
	if causes == nil {
		return nil
	}
	wantCauses, wantRemediations := FlattenProbableCauses(*causes)
	var errs []error
	if probableCause != nil && !slices.Equal(*probableCause, wantCauses) {
		errs = append(errs, contractErrorf(prefix+"probableCause", "is not the list derived from probableCauses"))
	}
	if suggestedRemediation != nil && !slices.Equal(*suggestedRemediation, wantRemediations) {
		errs = append(errs, contractErrorf(prefix+"suggestedRemediation", "is not the list derived from probableCauses"))
	}
	return errors.Join(errs...)
}

// FlatLists returns the definition's flat lists: derived from its nested
// causes when it has them, otherwise the unpaired lists it carries.
func (d ErrorDefinition) FlatLists() (probableCause, suggestedRemediation []string) {
	if d.ProbableCauses != nil {
		return FlattenProbableCauses(*d.ProbableCauses)
	}
	return derefStrings(d.ProbableCause), derefStrings(d.SuggestedRemediation)
}

func derefStrings(list *[]string) []string {
	if list == nil {
		return []string{}
	}
	return slices.Clone(*list)
}

// Validate checks the rules of a definition that JSON Schema cannot state:
// code is the component name, a hyphen and numericCode; the nested causes
// follow ValidateProbableCauses; and flat lists carried beside them equal the
// derivation. Validate the shape against the schema first. The returned
// error joins one *ContractError per broken rule, or is nil.
func (d ErrorDefinition) Validate() error {
	return d.validate("")
}

func (d ErrorDefinition) validate(prefix string) error {
	var errs []error
	if want := d.Component.Name + "-" + d.NumericCode; d.Code != want {
		errs = append(errs, contractErrorf(prefix+"code", "code %q is not %q (component name, hyphen, numericCode)", d.Code, want))
	}
	if d.ProbableCauses != nil {
		errs = append(errs, ValidateProbableCauses(*d.ProbableCauses, prefix+"probableCauses"))
	}
	errs = append(errs, ValidateFlatLists(d.ProbableCauses, d.ProbableCause, d.SuggestedRemediation, prefix))
	return errors.Join(errs...)
}

// Validate checks every definition in the index and that no code is listed
// twice for one component. Pass requireReferenceURL for the published index,
// where every entry links to its page; a component's export may omit them.
func (x ErrorReferenceIndex) Validate(requireReferenceURL bool) error {
	var errs []error
	seen := map[string]bool{}
	for i, definition := range x.Errors {
		prefix := fmt.Sprintf("errors[%d].", i)
		errs = append(errs, definition.validate(prefix))
		key := definition.Component.Type + "/" + definition.Component.Name + "/" + definition.Code
		if seen[key] {
			errs = append(errs, contractErrorf(prefix+"code", "code %s is listed more than once", key))
		}
		seen[key] = true
		if requireReferenceURL && (definition.ReferenceURL == nil || *definition.ReferenceURL == "") {
			errs = append(errs, contractErrorf(prefix+"referenceUrl", "%s has no referenceUrl", definition.Code))
		}
	}
	return errors.Join(errs...)
}
